BEGIN;
-- Claire is deliberately a narrow, private curriculum drafting boundary. It never
-- reads student/family/staff identity, assessment, attendance, testing, payment,
-- messages, source URLs, raw files, or Teaching Studio assessments/notes.
INSERT INTO hon.permissions(code,description,is_sensitive,is_staff_assignable) VALUES
 ('teaching.assistant.use','Complete direct staff curriculum teaching draft requests and approved internal Teaching Studio draft saves',true,true)
ON CONFLICT (code) DO NOTHING;
INSERT INTO hon.role_permissions(role_id,organization_id,permission_code)
 SELECT id,organization_id,'teaching.assistant.use' FROM hon.roles WHERE is_system_role AND code='OWNER' ON CONFLICT DO NOTHING;

-- Add one closed planner class without weakening prior task/risk constraints.
ALTER TABLE hon.ai_invocation_plans DROP CONSTRAINT ai_invocation_plans_task_class_check, DROP CONSTRAINT ai_invocation_plans_check;
ALTER TABLE hon.ai_invocation_plans ADD CHECK(task_class IN('SUMMARIZE','ANALYZE','DRAFT_MARKETING','DRAFT_TEACHING')),
 ADD CHECK((task_class='SUMMARIZE' AND risk_class='LOW') OR (task_class IN('ANALYZE','DRAFT_MARKETING','DRAFT_TEACHING') AND risk_class='MODERATE'));
CREATE OR REPLACE FUNCTION hon.validate_ai_invocation_plan_input(p_data jsonb) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE keys text[]:=ARRAY['expectedVersion','expectedState','agentKey','modality','taskClass','inputBudget','outputBudget','maxProviderCostMicrounits']; f text;
BEGIN
 IF p_data IS NULL OR jsonb_typeof(p_data)<>'object' OR NOT p_data ?& keys OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k<>ALL(keys)) THEN RAISE EXCEPTION 'Invalid AI planning metadata shape' USING ERRCODE='22023'; END IF;
 FOREACH f IN ARRAY ARRAY['expectedVersion','inputBudget','outputBudget','maxProviderCostMicrounits'] LOOP IF jsonb_typeof(p_data->f)<>'number' OR p_data->>f !~ '^[0-9]+$' OR (p_data->>f)::numeric>2147483646 THEN RAISE EXCEPTION 'Invalid AI planning integer' USING ERRCODE='22023'; END IF; END LOOP;
 IF (p_data->>'expectedVersion')::integer<1 OR (p_data->>'inputBudget')::integer NOT BETWEEN 1 AND 128000 OR (p_data->>'outputBudget')::integer NOT BETWEEN 1 AND 16000 OR (p_data->>'maxProviderCostMicrounits')::integer NOT BETWEEN 0 AND 1000000 THEN RAISE EXCEPTION 'AI planning budget or version out of range' USING ERRCODE='22023'; END IF;
 FOREACH f IN ARRAY ARRAY['expectedState','agentKey','modality','taskClass'] LOOP IF jsonb_typeof(p_data->f)<>'string' THEN RAISE EXCEPTION 'Invalid AI planning enum' USING ERRCODE='22023'; END IF; END LOOP;
 IF p_data->>'expectedState' NOT IN('READY','THINKING') OR p_data->>'agentKey' NOT IN('alex','chad','maya','marcus','jordan','claire','lena','eian') OR p_data->>'modality'<>'TEXT' OR p_data->>'taskClass' NOT IN('SUMMARIZE','ANALYZE','DRAFT_MARKETING','DRAFT_TEACHING') THEN RAISE EXCEPTION 'Unregistered AI planning metadata' USING ERRCODE='22023'; END IF;
END $$;

CREATE TABLE hon.teaching_ai_invocations (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, school_id uuid NOT NULL,
 requested_by uuid NOT NULL REFERENCES hon.principals(id), curriculum_id uuid NOT NULL, curriculum_version integer NOT NULL,
 work_item_id uuid NOT NULL, plan_id uuid, provider_request_id uuid NOT NULL DEFAULT gen_random_uuid(),
 brief_text text, request_hash text NOT NULL, idempotency_key uuid NOT NULL,
 status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','CONFIGURATION_REQUIRED','BLOCKED','SENDING','UNKNOWN','FAILED','AWAITING_APPROVAL','SAVED','REJECTED')),
 reason text CHECK(reason IN('CONFIGURATION_REQUIRED','NO_ELIGIBLE_ROUTE','CUSTOMER_BUDGET_EXCEEDED','UNSUPPORTED_PROVIDER','INVALID_REQUEST','PROVIDER_REJECTED','PROVIDER_UNKNOWN','ROUTE_STALE','RESULT_BUDGET_EXCEEDED')),
 reserved_credits integer NOT NULL DEFAULT 0 CHECK(reserved_credits BETWEEN 0 AND 6), action_request_id uuid, usage_id uuid REFERENCES hon.ai_usage_ledger(id), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 FOREIGN KEY(curriculum_id,organization_id,school_id) REFERENCES hon.curricula(id,organization_id,school_id),
 FOREIGN KEY(work_item_id,organization_id,school_id) REFERENCES hon.work_items(id,organization_id,school_id),
 FOREIGN KEY(action_request_id,organization_id,school_id) REFERENCES hon.action_requests(id,organization_id,school_id), FOREIGN KEY(plan_id) REFERENCES hon.ai_invocation_plans(id),
 UNIQUE(id,organization_id,school_id), UNIQUE(organization_id,school_id,requested_by,idempotency_key), UNIQUE(provider_request_id), UNIQUE(work_item_id), UNIQUE(plan_id), UNIQUE(action_request_id), UNIQUE(usage_id)
);
CREATE TABLE hon.teaching_ai_drafts (
 invocation_id uuid PRIMARY KEY, organization_id uuid NOT NULL, school_id uuid NOT NULL, curriculum_id uuid NOT NULL, title text NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 FOREIGN KEY(invocation_id,organization_id,school_id) REFERENCES hon.teaching_ai_invocations(id,organization_id,school_id), FOREIGN KEY(curriculum_id,organization_id,school_id) REFERENCES hon.curricula(id,organization_id,school_id)
);
-- A saved Claire result is a private Teaching Studio draft evidence item, not a lesson-plan revision or publication.
CREATE TABLE hon.teaching_studio_ai_drafts (
 invocation_id uuid PRIMARY KEY, organization_id uuid NOT NULL, school_id uuid NOT NULL, curriculum_id uuid NOT NULL, action_request_id uuid NOT NULL, title text NOT NULL, content text NOT NULL, saved_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 FOREIGN KEY(invocation_id,organization_id,school_id) REFERENCES hon.teaching_ai_invocations(id,organization_id,school_id), FOREIGN KEY(curriculum_id,organization_id,school_id) REFERENCES hon.curricula(id,organization_id,school_id), FOREIGN KEY(action_request_id,organization_id,school_id) REFERENCES hon.action_requests(id,organization_id,school_id)
);
CREATE FUNCTION hon.teaching_assistant_safe_text(v text,n integer,allow_null boolean DEFAULT false) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT (allow_null AND v IS NULL) OR (v IS NOT NULL AND length(btrim(v)) BETWEEN 1 AND n AND v !~* '(-----BEGIN|Bearer[[:space:]]+|\msk[-_][A-Za-z0-9_-]+|\meyJ[A-Za-z0-9_-]+\.eyJ|(?:api[ _-]?key|password|secret|authorization)[[:space:]]*[:=]|https?://|\mwww\.|[\x01-\x08\x0b\x0c\x0e-\x1f\x7f])')
$$;
ALTER TABLE hon.teaching_ai_invocations ADD CHECK(hon.teaching_assistant_safe_text(brief_text,1200,true)), ADD CHECK(request_hash~'^[a-f0-9]{64}$');
ALTER TABLE hon.teaching_ai_drafts ADD CHECK(hon.teaching_assistant_safe_text(title,160)), ADD CHECK(hon.teaching_assistant_safe_text(content,6000));
ALTER TABLE hon.teaching_studio_ai_drafts ADD CHECK(hon.teaching_assistant_safe_text(title,160)), ADD CHECK(hon.teaching_assistant_safe_text(content,6000));

CREATE FUNCTION hon.guard_teaching_assistant() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,hon AS $$
BEGIN
 IF TG_OP IN('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'IMMUTABLE_TEACHING_ASSISTANT' USING ERRCODE='42501'; END IF;
 IF TG_TABLE_NAME='teaching_ai_invocations' AND ((to_jsonb(NEW)-ARRAY['plan_id','status','reason','reserved_credits','action_request_id','usage_id','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['plan_id','status','reason','reserved_credits','action_request_id','usage_id','updated_at']) OR (OLD.plan_id IS NOT NULL AND NEW.plan_id IS DISTINCT FROM OLD.plan_id) OR (OLD.action_request_id IS NOT NULL AND NEW.action_request_id IS DISTINCT FROM OLD.action_request_id) OR (OLD.usage_id IS NOT NULL AND NEW.usage_id IS DISTINCT FROM OLD.usage_id)) THEN RAISE EXCEPTION 'IMMUTABLE_TEACHING_BINDING' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['teaching_ai_invocations','teaching_ai_drafts','teaching_studio_ai_drafts'] LOOP EXECUTE format('ALTER TABLE hon.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE hon.%I FORCE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON hon.%I FROM PUBLIC',t); EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON hon.%I FOR EACH ROW EXECUTE FUNCTION hon.guard_teaching_assistant()',t||'_immutable',t); EXECUTE format('CREATE TRIGGER %I BEFORE TRUNCATE ON hon.%I FOR EACH STATEMENT EXECUTE FUNCTION hon.guard_teaching_assistant()',t||'_no_truncate',t); END LOOP; END $$;

-- A no-selector resolver returns a scope only when this direct human has exactly one eligible current staff school.
CREATE FUNCTION hon.resolve_teaching_assistant_scope(p_subject text) RETURNS TABLE(principal_id uuid,organization_id uuid,school_id uuid) LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,hon AS $$
 WITH eligible AS (SELECT DISTINCT p.id principal_id,g.organization_id,g.school_id FROM hon.users u JOIN hon.principals p ON p.user_id=u.id JOIN hon.principal_role_grants g ON g.principal_id=p.id JOIN hon.organizations o ON o.id=g.organization_id AND o.status='ACTIVE' JOIN hon.schools s ON s.id=g.school_id AND s.organization_id=g.organization_id AND s.status='ACTIVE' WHERE u.external_subject=p_subject AND p.principal_type='HUMAN_USER' AND p.is_active AND (SELECT count(*) FROM hon.principals x WHERE x.user_id=u.id AND x.principal_type='HUMAN_USER' AND x.is_active)=1 AND NOT EXISTS(SELECT 1 FROM hon.hq_operator_grants h WHERE h.principal_id=p.id) AND NOT EXISTS(SELECT 1 FROM hon.principal_role_grants pg JOIN hon.roles pr ON pr.id=pg.role_id AND pr.organization_id=pg.organization_id WHERE pg.principal_id=p.id AND pr.code IN('PARENT','GUARDIAN','STUDENT','FAMILY','HQ') AND pg.revoked_at IS NULL AND pg.effective_from<=clock_timestamp() AND (pg.effective_until IS NULL OR pg.effective_until>clock_timestamp())) AND hon.staff_member_eligible(p.id,g.organization_id,g.school_id) AND EXISTS(SELECT 1 FROM hon.organization_entitlements e WHERE e.organization_id=g.organization_id AND e.status='ACTIVE' AND e.tier='COMPLETE' AND e.effective_from<=clock_timestamp() AND (e.effective_until IS NULL OR e.effective_until>clock_timestamp())) AND NOT EXISTS(SELECT 1 FROM hon.organization_entitlements e WHERE e.organization_id=g.organization_id AND e.status='ACTIVE' AND e.effective_from<=clock_timestamp() AND (e.effective_until IS NULL OR e.effective_until>clock_timestamp()) AND e.tier<>'COMPLETE') AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['teaching.studio.read','teaching.assistant.use','ai.invocation.plan']) q(code) WHERE NOT hon.principal_has_school_permission(p.id,g.organization_id,g.school_id,q.code))) SELECT principal_id,organization_id,school_id FROM eligible WHERE (SELECT count(*) FROM eligible)=1
$$;
CREATE FUNCTION hon.require_teaching_assistant_actor(p_subject text,writing boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,hon AS $$
DECLARE actor uuid; org uuid:=hon.current_organization_id(); school uuid:=hon.current_school_id(); active_complete bigint;
BEGIN
 IF current_setting('app.hon_principal_type',true) IS DISTINCT FROM 'HUMAN_USER' OR current_setting('app.hon_source',true) IS DISTINCT FROM 'HUMAN_UI' OR nullif(current_setting('app.hon_action_request_id',true),'') IS NOT NULL OR nullif(current_setting('app.hon_delegated_by_principal_id',true),'') IS NOT NULL THEN RAISE EXCEPTION 'CLAIRE_HUMAN_STAFF_REQUIRED' USING ERRCODE='42501'; END IF;
 actor:=hon.lock_teaching_studio_actor(p_subject,'teaching.studio.read',writing);
 SELECT count(*) INTO active_complete FROM hon.organization_entitlements WHERE organization_id=org AND status='ACTIVE' AND effective_from<=clock_timestamp() AND (effective_until IS NULL OR effective_until>clock_timestamp()) AND tier='COMPLETE';
 IF active_complete<>1 OR EXISTS(SELECT 1 FROM hon.organization_entitlements WHERE organization_id=org AND status='ACTIVE' AND effective_from<=clock_timestamp() AND (effective_until IS NULL OR effective_until>clock_timestamp()) AND tier<>'COMPLETE') OR NOT hon.principal_has_school_permission(actor,org,school,'teaching.assistant.use') OR NOT hon.principal_has_school_permission(actor,org,school,'ai.invocation.plan') OR EXISTS(SELECT 1 FROM hon.hq_operator_grants WHERE principal_id=actor) OR EXISTS(SELECT 1 FROM hon.principal_role_grants g JOIN hon.roles r ON r.id=g.role_id AND r.organization_id=g.organization_id WHERE g.principal_id=actor AND r.code IN('PARENT','GUARDIAN','STUDENT','FAMILY','HQ') AND g.revoked_at IS NULL AND g.effective_from<=clock_timestamp() AND (g.effective_until IS NULL OR g.effective_until>clock_timestamp())) THEN RAISE EXCEPTION 'CLAIRE_HUMAN_STAFF_REQUIRED' USING ERRCODE='42501'; END IF;
 RETURN actor;
END $$;
CREATE FUNCTION hon.teaching_assistant_event(p_id uuid,p_event text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$
DECLARE i hon.teaching_ai_invocations%ROWTYPE; rid uuid:=nullif(current_setting('app.hon_request_id',true),'')::uuid; payload jsonb;
BEGIN SELECT * INTO STRICT i FROM hon.teaching_ai_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id(); payload:=jsonb_build_object('invocationId',i.id,'workItemId',i.work_item_id,'status',i.status,'reason',i.reason,'privateTeachingDraftOnly',true); INSERT INTO hon.audit_events(organization_id,school_id,actor_principal_id,source,action_code,entity_type,entity_id,next_state,result,request_id,correlation_id,action_request_id) VALUES(i.organization_id,i.school_id,nullif(current_setting('app.hon_principal_id',true),'')::uuid,'HUMAN_UI',p_event,'TEACHING_AI_INVOCATION',i.id,payload,'SUCCEEDED',rid,rid,i.action_request_id); INSERT INTO hon.outbox_events(organization_id,school_id,event_type,schema_version,aggregate_type,aggregate_id,aggregate_version,correlation_id,causation_id,payload) VALUES(i.organization_id,i.school_id,p_event,1,'TEACHING_AI_INVOCATION',i.id,1,rid,rid,payload); END $$;
CREATE FUNCTION hon.read_teaching_invocation(p_subject text,p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$
DECLARE actor uuid:=hon.require_teaching_assistant_actor(p_subject,false); result jsonb;
BEGIN SELECT jsonb_build_object('id',i.id,'schoolId',i.school_id,'curriculumId',i.curriculum_id,'workItemId',i.work_item_id,'status',CASE WHEN i.status='SENDING' AND i.updated_at<clock_timestamp()-interval '30 seconds' THEN 'UNKNOWN' ELSE i.status END,'reason',i.reason,'actionRequestId',i.action_request_id,'draft',CASE WHEN d.invocation_id IS NULL THEN NULL ELSE jsonb_build_object('title',d.title,'content',d.content) END,'inputTokens',u.input_units,'outputTokens',u.output_units,'providerCostMicrounits',u.provider_cost_microunits,'customerCredits',u.customer_credits) INTO result FROM hon.teaching_ai_invocations i LEFT JOIN hon.teaching_ai_drafts d ON d.invocation_id=i.id LEFT JOIN hon.ai_usage_ledger u ON u.id=i.usage_id WHERE i.id=p_id AND i.organization_id=hon.current_organization_id() AND i.school_id=hon.current_school_id() AND i.requested_by=actor; IF result IS NULL THEN RAISE EXCEPTION 'TEACHING_INVOCATION_NOT_FOUND' USING ERRCODE='P0002'; END IF; RETURN result; END $$;
CREATE FUNCTION hon.begin_teaching_request(p_subject text,p_input jsonb,p_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$
DECLARE actor uuid:=hon.require_teaching_assistant_actor(p_subject,true); org uuid:=hon.current_organization_id(); school uuid:=hon.current_school_id(); c hon.curricula%ROWTYPE; i hon.teaching_ai_invocations%ROWTYPE; wid uuid; fp text;
BEGIN IF p_key IS NULL OR p_input IS NULL OR jsonb_typeof(p_input)<>'object' OR NOT p_input?'curriculumId' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_input) k WHERE k NOT IN('curriculumId','brief')) OR jsonb_typeof(p_input->'curriculumId')<>'string' OR p_input->>'curriculumId' !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' OR (p_input?'brief' AND (jsonb_typeof(p_input->'brief')<>'string' OR NOT hon.teaching_assistant_safe_text(p_input->>'brief',1200))) THEN RAISE EXCEPTION 'INVALID_TEACHING_REQUEST' USING ERRCODE='22023'; END IF; fp:=encode(sha256(convert_to(p_input::text,'UTF8')),'hex'); SELECT * INTO i FROM hon.teaching_ai_invocations WHERE organization_id=org AND school_id=school AND requested_by=actor AND idempotency_key=p_key FOR UPDATE; IF FOUND THEN IF i.request_hash<>fp THEN RAISE EXCEPTION 'TEACHING_REPLAY_SWAP' USING ERRCODE='23505'; END IF; RETURN hon.read_teaching_invocation(p_subject,i.id); END IF; SELECT * INTO c FROM hon.curricula WHERE id=(p_input->>'curriculumId')::uuid AND organization_id=org AND school_id=school AND lifecycle='PUBLISHED' FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'PUBLISHED_CURRICULUM_NOT_FOUND' USING ERRCODE='P0002'; END IF; INSERT INTO hon.work_items(organization_id,school_id,work_type,status,subject_type,subject_id,payload,correlation_id) VALUES(org,school,'AI_DRAFT_TEACHING','READY','CURRICULUM',c.id,'{}',nullif(current_setting('app.hon_request_id',true),'')::uuid) RETURNING id INTO wid; INSERT INTO hon.teaching_ai_invocations(organization_id,school_id,requested_by,curriculum_id,curriculum_version,work_item_id,brief_text,request_hash,idempotency_key) VALUES(org,school,actor,c.id,c.version,wid,p_input->>'brief',fp,p_key) RETURNING * INTO i; PERFORM hon.teaching_assistant_event(i.id,'teaching.assistant.requested'); RETURN hon.read_teaching_invocation(p_subject,i.id); END $$;
CREATE FUNCTION hon.teaching_planning_reference(p_subject text,p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$
DECLARE actor uuid:=hon.require_teaching_assistant_actor(p_subject,true); i hon.teaching_ai_invocations%ROWTYPE; w hon.work_items%ROWTYPE;
BEGIN SELECT * INTO i FROM hon.teaching_ai_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() AND requested_by=actor FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'TEACHING_INVOCATION_NOT_FOUND' USING ERRCODE='P0002'; END IF; IF i.status='SENDING' AND i.updated_at<clock_timestamp()-interval '30 seconds' THEN UPDATE hon.teaching_ai_invocations SET status='UNKNOWN',reason='PROVIDER_UNKNOWN',updated_at=clock_timestamp() WHERE id=i.id; UPDATE hon.work_items SET status='NEEDS_ATTENTION',version=version+1 WHERE id=i.work_item_id; PERFORM hon.teaching_assistant_event(i.id,'teaching.assistant.unknown'); RETURN NULL; END IF; IF i.status NOT IN('PENDING','CONFIGURATION_REQUIRED','BLOCKED') THEN RETURN NULL; END IF; SELECT * INTO STRICT w FROM hon.work_items WHERE id=i.work_item_id AND organization_id=i.organization_id AND school_id=i.school_id FOR UPDATE; IF i.plan_id IS NULL AND w.status<>'READY' THEN UPDATE hon.work_items SET status='READY',version=version+1 WHERE id=w.id RETURNING * INTO w; END IF; RETURN jsonb_build_object('planId',i.plan_id,'workItemId',w.id,'workVersion',w.version); END $$;
CREATE FUNCTION hon.prepare_teaching_invocation(p_subject text,p_id uuid,p_plan uuid,p_ready boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$
DECLARE actor uuid:=hon.require_teaching_assistant_actor(p_subject,true); i hon.teaching_ai_invocations%ROWTYPE; p hon.ai_invocation_plans%ROWTYPE; used numeric; reserved numeric; why text; facts jsonb;
BEGIN SELECT * INTO i FROM hon.teaching_ai_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() AND requested_by=actor FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'TEACHING_INVOCATION_NOT_FOUND' USING ERRCODE='P0002'; END IF; IF i.status='SENDING' AND i.updated_at<clock_timestamp()-interval '30 seconds' THEN UPDATE hon.teaching_ai_invocations SET status='UNKNOWN',reason='PROVIDER_UNKNOWN',updated_at=clock_timestamp() WHERE id=i.id; PERFORM hon.teaching_assistant_event(i.id,'teaching.assistant.unknown'); RETURN NULL; END IF; IF i.status NOT IN('PENDING','CONFIGURATION_REQUIRED','BLOCKED') THEN RETURN NULL; END IF; IF p_plan IS NULL THEN UPDATE hon.teaching_ai_invocations SET status='BLOCKED',reason='NO_ELIGIBLE_ROUTE' WHERE id=i.id; UPDATE hon.work_items SET status='NEEDS_ATTENTION',version=version+1 WHERE id=i.work_item_id; PERFORM hon.teaching_assistant_event(i.id,'teaching.assistant.blocked'); RETURN NULL; END IF; SELECT * INTO p FROM hon.ai_invocation_plans WHERE id=p_plan AND organization_id=i.organization_id AND school_id=i.school_id AND work_item_id=i.work_item_id AND task_class='DRAFT_TEACHING' AND agent_key='claire' AND input_budget=4096 AND output_budget=1024 AND max_provider_cost_microunits=100000; IF NOT FOUND OR (i.plan_id IS NOT NULL AND i.plan_id<>p_plan) THEN RAISE EXCEPTION 'TEACHING_PLAN_SWAP' USING ERRCODE='42501'; END IF; PERFORM 1 FROM hon.hq_ai_provider_connections WHERE provider_id=p.provider_id FOR SHARE; PERFORM 1 FROM hon.hq_ai_model_catalog WHERE catalog_id=p.catalog_id FOR SHARE; PERFORM 1 FROM hon.hq_ai_routing_policies WHERE policy_id=p.routing_policy_id FOR SHARE; PERFORM 1 FROM hon.hq_ai_routing_candidates WHERE policy_id=p.routing_policy_id FOR SHARE;
 IF p.provider_id<>'OPENROUTER' THEN why:='UNSUPPORTED_PROVIDER'; ELSIF NOT EXISTS(SELECT 1 FROM hon.hq_ai_provider_connections pc JOIN hon.hq_ai_model_catalog m ON m.provider_id=pc.provider_id JOIN hon.hq_ai_routing_candidates rc ON rc.catalog_id=m.catalog_id JOIN hon.hq_ai_routing_policies rp ON rp.policy_id=rc.policy_id WHERE pc.provider_id=p.provider_id AND pc.state='HEALTHY' AND pc.version=p.provider_version AND m.catalog_id=p.catalog_id AND m.model_id=p.model_id AND m.version=p.catalog_version AND m.active AND m.cost_unit='TOKEN' AND 'TEXT'=ANY(m.capabilities) AND 'TEXT'=ANY(m.modalities) AND m.effective_from<=clock_timestamp() AND (m.effective_until IS NULL OR m.effective_until>clock_timestamp()) AND rp.policy_id=p.routing_policy_id AND rp.organization_id=i.organization_id AND rp.school_id=i.school_id AND rp.version=p.routing_policy_version AND rp.active AND rp.capability='TEXT' AND rp.effective_from<=clock_timestamp() AND (rp.effective_until IS NULL OR rp.effective_until>clock_timestamp()) AND m.unit_cost_micros*5120<=LEAST(rp.max_cost_micros,p.max_provider_cost_microunits)) THEN why:='ROUTE_STALE'; ELSIF NOT p_ready THEN why:='CONFIGURATION_REQUIRED'; END IF;
 SELECT coalesce(sum(customer_credits),0) INTO used FROM hon.ai_usage_ledger WHERE organization_id=i.organization_id AND occurred_at>=date_trunc('month',clock_timestamp() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AND occurred_at<(date_trunc('month',clock_timestamp() AT TIME ZONE 'UTC')+interval '1 month') AT TIME ZONE 'UTC'; SELECT coalesce(sum(reserved_credits),0) INTO reserved FROM hon.teaching_ai_invocations WHERE organization_id=i.organization_id; IF why IS NULL AND used+reserved+p.customer_credit_estimate>12000 THEN why:='CUSTOMER_BUDGET_EXCEEDED'; END IF; UPDATE hon.teaching_ai_invocations SET plan_id=p.id,status=CASE WHEN why IS NULL THEN 'SENDING' WHEN why='CONFIGURATION_REQUIRED' THEN 'CONFIGURATION_REQUIRED' ELSE 'BLOCKED' END,reason=why,reserved_credits=CASE WHEN why IS NULL THEN p.customer_credit_estimate ELSE 0 END,updated_at=clock_timestamp() WHERE id=i.id; UPDATE hon.work_items SET status=CASE WHEN why IS NULL THEN 'WORKING' ELSE 'NEEDS_ATTENTION' END,version=version+1,updated_at=clock_timestamp() WHERE id=i.work_item_id; PERFORM hon.teaching_assistant_event(i.id,'teaching.assistant.prepared'); IF why IS NOT NULL THEN RETURN NULL; END IF;
 SELECT jsonb_build_object('curriculum',jsonb_build_object('id',c.id,'name',c.name,'description',coalesce(c.description,''),'modelCode',c.model_code,'version',c.version),'ranks',coalesce(jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'order',r.progression_order,'requirements',coalesce((SELECT jsonb_agg(jsonb_build_object('code',q.requirement_code,'kind',q.requirement_kind,'required',q.is_required,'version',q.version) ORDER BY q.requirement_code) FROM hon.curriculum_requirements q WHERE q.curriculum_rank_id=r.id AND q.organization_id=i.organization_id AND q.school_id=i.school_id),'[]'::jsonb)) ORDER BY r.progression_order),'[]'::jsonb),'brief',i.brief_text) INTO facts FROM hon.curricula c LEFT JOIN hon.curriculum_ranks r ON r.curriculum_id=c.id AND r.organization_id=c.organization_id AND r.school_id=c.school_id WHERE c.id=i.curriculum_id AND c.organization_id=i.organization_id AND c.school_id=i.school_id AND c.lifecycle='PUBLISHED' GROUP BY c.id,c.name,c.description,c.model_code,c.version,i.brief_text; IF facts IS NULL THEN RAISE EXCEPTION 'PUBLISHED_CURRICULUM_NOT_FOUND' USING ERRCODE='P0002'; END IF; RETURN jsonb_build_object('providerId',p.provider_id,'modelId',p.model_id,'providerRequestId',i.provider_request_id,'request','Approved curriculum facts only: '||facts::text,'inputBudget',p.input_budget,'outputBudget',p.output_budget,'maxCostMicrounits',p.max_provider_cost_microunits); END $$;
CREATE FUNCTION hon.fail_teaching_invocation(p_subject text,p_id uuid,p_outcome text,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE actor uuid:=hon.require_teaching_assistant_actor(p_subject,true); i hon.teaching_ai_invocations%ROWTYPE; BEGIN IF p_outcome NOT IN('PRE_SEND','FAILED','UNKNOWN') OR p_reason NOT IN('CONFIGURATION_REQUIRED','UNSUPPORTED_PROVIDER','INVALID_REQUEST','PROVIDER_REJECTED','PROVIDER_UNKNOWN') THEN RAISE EXCEPTION 'INVALID_TEACHING_OUTCOME' USING ERRCODE='22023'; END IF; SELECT * INTO i FROM hon.teaching_ai_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() AND requested_by=actor FOR UPDATE; IF NOT FOUND OR i.status<>'SENDING' THEN RAISE EXCEPTION 'TEACHING_OUTCOME_REPLAY' USING ERRCODE='40001'; END IF; UPDATE hon.teaching_ai_invocations SET status=CASE WHEN p_outcome='PRE_SEND' THEN 'CONFIGURATION_REQUIRED' ELSE p_outcome END,reason=p_reason,reserved_credits=CASE WHEN p_outcome='UNKNOWN' THEN reserved_credits ELSE 0 END,updated_at=clock_timestamp() WHERE id=i.id; UPDATE hon.work_items SET status='NEEDS_ATTENTION',version=version+1 WHERE id=i.work_item_id; PERFORM hon.teaching_assistant_event(i.id,'teaching.assistant.provider_result'); END $$;
CREATE FUNCTION hon.record_teaching_result(p_subject text,p_id uuid,p_result jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$
DECLARE actor uuid:=hon.require_teaching_assistant_actor(p_subject,true); i hon.teaching_ai_invocations%ROWTYPE; p hon.ai_invocation_plans%ROWTYPE; uid uuid; credits integer; d jsonb:=p_result->'draft'; over boolean;
BEGIN SELECT * INTO i FROM hon.teaching_ai_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() AND requested_by=actor FOR UPDATE; IF NOT FOUND OR i.status<>'SENDING' OR i.usage_id IS NOT NULL THEN RAISE EXCEPTION 'TEACHING_OUTCOME_REPLAY' USING ERRCODE='40001'; END IF; SELECT * INTO STRICT p FROM hon.ai_invocation_plans WHERE id=i.plan_id; IF p_result IS NULL OR jsonb_typeof(p_result)<>'object' OR NOT p_result?&ARRAY['draft','inputTokens','outputTokens','providerCostMicrounits'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_result) k WHERE k NOT IN('draft','inputTokens','outputTokens','providerCostMicrounits')) OR jsonb_typeof(d)<>'object' OR NOT d?&ARRAY['title','content'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(d) k WHERE k NOT IN('title','content')) OR jsonb_typeof(d->'title')<>'string' OR jsonb_typeof(d->'content')<>'string' OR NOT hon.teaching_assistant_safe_text(d->>'title',160) OR NOT hon.teaching_assistant_safe_text(d->>'content',6000) OR (p_result->>'inputTokens')!~'^[0-9]+$' OR (p_result->>'outputTokens')!~'^[0-9]+$' OR (p_result->>'providerCostMicrounits')!~'^[0-9]+$' THEN RAISE EXCEPTION 'INVALID_TEACHING_RESULT' USING ERRCODE='22023'; END IF; credits:=((p_result->>'inputTokens')::integer+(p_result->>'outputTokens')::integer+999)/1000; over:=(p_result->>'inputTokens')::integer>p.input_budget OR (p_result->>'outputTokens')::integer>p.output_budget OR (p_result->>'providerCostMicrounits')::bigint>p.max_provider_cost_microunits OR credits>i.reserved_credits; INSERT INTO hon.ai_usage_ledger(organization_id,school_id,initiator_principal_id,work_item_id,provider_code,model_code,modality,input_units,output_units,provider_cost_microunits,customer_credits,correlation_id) VALUES(i.organization_id,i.school_id,actor,i.work_item_id,p.provider_id,p.model_id,'TEXT',(p_result->>'inputTokens')::bigint,(p_result->>'outputTokens')::bigint,(p_result->>'providerCostMicrounits')::bigint,credits,nullif(current_setting('app.hon_request_id',true),'')::uuid) RETURNING id INTO uid; UPDATE hon.teaching_ai_invocations SET usage_id=uid,reserved_credits=0,status=CASE WHEN over THEN 'FAILED' ELSE status END,reason=CASE WHEN over THEN 'RESULT_BUDGET_EXCEEDED' ELSE NULL END WHERE id=i.id; IF over THEN UPDATE hon.work_items SET status='FAILED',version=version+1 WHERE id=i.work_item_id; PERFORM hon.teaching_assistant_event(i.id,'teaching.assistant.budget_failed'); RETURN NULL; END IF; INSERT INTO hon.teaching_ai_drafts(invocation_id,organization_id,school_id,curriculum_id,title,content) VALUES(i.id,i.organization_id,i.school_id,i.curriculum_id,d->>'title',d->>'content'); RETURN jsonb_build_object('invocationId',i.id,'curriculumId',i.curriculum_id,'curriculumVersion',i.curriculum_version,'title',d->>'title','content',d->>'content'); END $$;
CREATE FUNCTION hon.bind_teaching_proposal(p_subject text,p_id uuid,p_action uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE actor uuid:=hon.require_teaching_assistant_actor(p_subject,true); i hon.teaching_ai_invocations%ROWTYPE; d hon.teaching_ai_drafts%ROWTYPE; BEGIN SELECT * INTO i FROM hon.teaching_ai_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() AND requested_by=actor FOR UPDATE; SELECT * INTO STRICT d FROM hon.teaching_ai_drafts WHERE invocation_id=i.id; IF i.status<>'SENDING' OR i.action_request_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM hon.action_requests a WHERE a.id=p_action AND a.organization_id=i.organization_id AND a.school_id=i.school_id AND a.requested_by_principal_id=actor AND a.action_code='teaching.draft.save' AND a.required_permission='teaching.assistant.use' AND a.effective_authority_mode='CONFIRM' AND a.status='AWAITING_APPROVAL' AND a.normalized_payload=jsonb_build_object('invocationId',i.id,'curriculumId',i.curriculum_id,'curriculumVersion',i.curriculum_version,'title',d.title,'content',d.content)) THEN RAISE EXCEPTION 'TEACHING_ACTION_BINDING' USING ERRCODE='42501'; END IF; UPDATE hon.teaching_ai_invocations SET action_request_id=p_action,status='AWAITING_APPROVAL',updated_at=clock_timestamp() WHERE id=i.id; UPDATE hon.work_items SET status='WAITING_FOR_APPROVAL',version=version+1 WHERE id=i.work_item_id; PERFORM hon.teaching_assistant_event(i.id,'teaching.assistant.drafted'); END $$;
CREATE FUNCTION hon.teaching_action_is_current(p_action uuid,p_payload jsonb) RETURNS boolean LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ SELECT EXISTS(SELECT 1 FROM hon.teaching_ai_invocations i JOIN hon.teaching_ai_drafts d ON d.invocation_id=i.id JOIN hon.curricula c ON c.id=i.curriculum_id AND c.organization_id=i.organization_id AND c.school_id=i.school_id WHERE i.action_request_id=p_action AND i.organization_id=hon.current_organization_id() AND i.school_id=hon.current_school_id() AND i.status='AWAITING_APPROVAL' AND c.lifecycle='PUBLISHED' AND c.version=i.curriculum_version AND p_payload=jsonb_build_object('invocationId',i.id,'curriculumId',i.curriculum_id,'curriculumVersion',i.curriculum_version,'title',d.title,'content',d.content)) $$;
CREATE FUNCTION hon.reject_teaching_draft(p_action uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE i hon.teaching_ai_invocations%ROWTYPE; BEGIN IF NOT hon.human_action_reviewer() THEN RAISE EXCEPTION 'REVIEW_REQUIRED' USING ERRCODE='42501'; END IF; SELECT * INTO i FROM hon.teaching_ai_invocations WHERE action_request_id=p_action AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() FOR UPDATE; IF NOT FOUND OR i.status<>'AWAITING_APPROVAL' OR NOT EXISTS(SELECT 1 FROM hon.action_requests a JOIN hon.action_approvals ap ON ap.action_request_id=a.id WHERE a.id=p_action AND a.status='DENIED' AND ap.decision='DENIED' AND ap.reviewed_payload_hash=a.payload_hash AND ap.reviewed_policy_version=a.policy_version AND ap.reviewer_principal_id<>i.requested_by) THEN RAISE EXCEPTION 'TEACHING_REJECTION_BINDING' USING ERRCODE='42501'; END IF; UPDATE hon.teaching_ai_invocations SET status='REJECTED',updated_at=clock_timestamp() WHERE id=i.id; UPDATE hon.work_items SET status='FAILED',version=version+1,result='{"reason":"HUMAN_REJECTED"}' WHERE id=i.work_item_id; PERFORM hon.teaching_assistant_event(i.id,'teaching.assistant.rejected'); END $$;
CREATE FUNCTION hon.save_approved_teaching_draft(p_subject text,p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE actor uuid:=hon.require_teaching_assistant_actor(p_subject,true); i hon.teaching_ai_invocations%ROWTYPE; a hon.action_requests%ROWTYPE; d hon.teaching_ai_drafts%ROWTYPE; BEGIN SELECT * INTO i FROM hon.teaching_ai_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() AND requested_by=actor FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'TEACHING_INVOCATION_NOT_FOUND' USING ERRCODE='P0002'; END IF; IF i.status='SAVED' THEN RETURN hon.read_teaching_invocation(p_subject,p_id); END IF; SELECT * INTO a FROM hon.action_requests WHERE id=i.action_request_id AND organization_id=i.organization_id AND school_id=i.school_id FOR UPDATE; SELECT * INTO STRICT d FROM hon.teaching_ai_drafts WHERE invocation_id=i.id FOR SHARE; IF i.status<>'AWAITING_APPROVAL' OR a.id IS NULL OR a.status<>'APPROVED' OR a.action_code<>'teaching.draft.save' OR a.required_permission<>'teaching.assistant.use' OR a.requested_by_principal_id<>actor OR a.delegated_by_principal_id IS NOT NULL OR a.effective_authority_mode<>'CONFIRM' OR a.approval_expires_at IS NULL OR a.approval_expires_at<=clock_timestamp() OR NOT hon.teaching_action_is_current(a.id,a.normalized_payload) OR NOT EXISTS(SELECT 1 FROM hon.action_approvals ap JOIN hon.principals p ON p.id=ap.reviewer_principal_id WHERE ap.action_request_id=a.id AND ap.decision='APPROVED' AND ap.reviewed_payload_hash=a.payload_hash AND ap.reviewed_policy_version=a.policy_version AND ap.reviewer_principal_id<>actor AND p.is_active AND p.principal_type='HUMAN_USER' AND NOT EXISTS(SELECT 1 FROM hon.hq_operator_grants h WHERE h.principal_id=p.id) AND NOT EXISTS(SELECT 1 FROM hon.principal_role_grants g JOIN hon.roles r ON r.id=g.role_id AND r.organization_id=g.organization_id WHERE g.principal_id=p.id AND r.code IN('PARENT','GUARDIAN','STUDENT','FAMILY','HQ') AND g.revoked_at IS NULL AND g.effective_from<=clock_timestamp() AND (g.effective_until IS NULL OR g.effective_until>clock_timestamp())) AND hon.principal_has_school_permission(p.id,i.organization_id,i.school_id,'action.approve')) THEN RAISE EXCEPTION 'TEACHING_APPROVAL_STALE' USING ERRCODE='42501'; END IF; INSERT INTO hon.teaching_studio_ai_drafts(invocation_id,organization_id,school_id,curriculum_id,action_request_id,title,content) VALUES(i.id,i.organization_id,i.school_id,i.curriculum_id,a.id,d.title,d.content); UPDATE hon.action_requests SET status='SUCCEEDED',verified_result=jsonb_build_object('invocationId',i.id,'curriculumId',i.curriculum_id,'internalOnly',true),updated_at=clock_timestamp() WHERE id=a.id; UPDATE hon.teaching_ai_invocations SET status='SAVED',updated_at=clock_timestamp() WHERE id=i.id; UPDATE hon.work_items SET status='COMPLETED',version=version+1,result=jsonb_build_object('invocationId',i.id,'curriculumId',i.curriculum_id,'privateTeachingDraftOnly',true),updated_at=clock_timestamp() WHERE id=i.work_item_id; PERFORM hon.teaching_assistant_event(i.id,'teaching.assistant.saved'); RETURN hon.read_teaching_invocation(p_subject,i.id); END $$;
DO $$ DECLARE f regprocedure; r text; BEGIN FOREACH f IN ARRAY ARRAY['hon.teaching_assistant_safe_text(text,integer,boolean)'::regprocedure,'hon.guard_teaching_assistant()'::regprocedure,'hon.resolve_teaching_assistant_scope(text)'::regprocedure,'hon.require_teaching_assistant_actor(text,boolean)'::regprocedure,'hon.teaching_assistant_event(uuid,text)'::regprocedure,'hon.read_teaching_invocation(text,uuid)'::regprocedure,'hon.begin_teaching_request(text,jsonb,uuid)'::regprocedure,'hon.teaching_planning_reference(text,uuid)'::regprocedure,'hon.prepare_teaching_invocation(text,uuid,uuid,boolean)'::regprocedure,'hon.fail_teaching_invocation(text,uuid,text,text)'::regprocedure,'hon.record_teaching_result(text,uuid,jsonb)'::regprocedure,'hon.bind_teaching_proposal(text,uuid,uuid)'::regprocedure,'hon.teaching_action_is_current(uuid,jsonb)'::regprocedure,'hon.reject_teaching_draft(uuid)'::regprocedure,'hon.save_approved_teaching_draft(text,uuid)'::regprocedure] LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f); END LOOP; IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='hon_runtime') THEN REVOKE ALL ON hon.teaching_ai_invocations,hon.teaching_ai_drafts,hon.teaching_studio_ai_drafts FROM hon_runtime; GRANT EXECUTE ON FUNCTION hon.resolve_teaching_assistant_scope(text),hon.read_teaching_invocation(text,uuid),hon.begin_teaching_request(text,jsonb,uuid),hon.teaching_planning_reference(text,uuid),hon.prepare_teaching_invocation(text,uuid,uuid,boolean),hon.fail_teaching_invocation(text,uuid,text,text),hon.record_teaching_result(text,uuid,jsonb),hon.bind_teaching_proposal(text,uuid,uuid),hon.teaching_action_is_current(uuid,jsonb),hon.reject_teaching_draft(uuid),hon.save_approved_teaching_draft(text,uuid) TO hon_runtime; END IF; FOR r IN SELECT rolname FROM pg_roles WHERE rolname IN('anon','authenticated','service_role') LOOP EXECUTE format('REVOKE ALL ON hon.teaching_ai_invocations,hon.teaching_ai_drafts,hon.teaching_studio_ai_drafts FROM %I',r); END LOOP; END $$;
COMMIT;
